INSERT INTO `settings` (`skey`, `svalue`, `notes`) VALUES
  ('title_tag', 'அருள்மிகு ஆனைமலை கருப்பராயர் திருக்கோவில் | Arulmiku Anaimalai Karupparayar Temple, Annur', 'Browser tab / search result title'),
  ('meta_description', 'அருள்மிகு ஆனைமலை கருப்பராயர் திருக்கோவில், அன்னூர், கோயம்புத்தூர் — கருப்பராயன், வேம்பரசு விநாயகர், மகா முனிஸ்வரர், சப்த கன்னிகள் சன்னதிகள். வரலாறு, திருவிழாக்கள், முகவரி மற்றும் தரிசன தகவல். Arulmiku Anaimalai Karupparayar Temple, Annur, Coimbatore District, Tamil Nadu.', 'Google search description (~160 chars)'),
  ('og_site_name', 'அருள்மிகு ஆனைமலை கருப்பராயர் திருக்கோவில்', 'Site name for social shares'),
  ('og_title', 'அருள்மிகு ஆனைமலை கருப்பராயர் திருக்கோவில், அன்னூர்', 'Title shown when the link is shared'),
  ('og_description', 'அன்னூர் ஆனைமலை கருப்பராயசுவாமி கோயில் — கோயம்புத்தூர் மாவட்டத்தின் புராதன கிராமக் கோயில். வரலாறு, சன்னதிகள், திருவிழாக்கள் மற்றும் வருகை தகவல்.', 'Description shown when shared'),
  ('twitter_description', 'அன்னூர் ஆனைமலை கருப்பராயசுவாமி கோயில் — வரலாறு, சன்னதிகள், திருவிழாக்கள் மற்றும் வருகை தகவல்.', 'Twitter card description'),
  ('og_url', 'https://REPLACE-WITH-DOMAIN/', 'Full https:// site address'),
  ('og_image', 'https://REPLACE-WITH-DOMAIN/images/gopuram-front.jpg', 'Full https:// URL of the share image'),
  ('brand_ta', 'அருள்மிகு ஆனைமலை கருப்பராயர்<br>திருக்கோவில்', 'Header name. <br> allowed'),
  ('phone_display', '098430 98927', 'Phone number as shown'),
  ('phone_link', '+919843098927', 'Dial link, e.g. +919843098927'),
  ('latitude', '11.2331743', 'Map latitude'),
  ('longitude', '77.0994511', 'Map longitude'),
  ('hero_image', 'hero-karupparayar.jpg', 'Circular hero photo'),
  ('hero_image_alt', 'மாலை அணிவித்த கருப்பராயர் சன்னதி — garlanded shrine at the Anaimalai Karupparayar temple', 'Hero photo description'),
  ('hero_title_ta', 'அருள்மிகு ஆனைமலை<br>கருப்பராயர் திருக்கோவில்', 'Main heading, Tamil. <br> allowed'),
  ('hero_title_en', 'Arulmiku Anaimalai Karupparayar Thirukkoyil', 'Main heading, English'),
  ('hero_subtitle_ta', 'அன்னூர், கோயம்புத்தூர் மாவட்டம், தமிழ்நாடு', 'Sub heading, Tamil'),
  ('hero_subtitle_en', 'Annur, Coimbatore District, Tamil Nadu, India — 641653', 'Sub heading, English'),
  ('hero_scroll_hint', 'கீழே உருட்டவும்', 'Scroll prompt text'),
  ('footer_temple_name', 'அருள்மிகு ஆனைமலை கருப்பராயர் திருக்கோவில், அன்னூர்', 'Footer temple name'),
  ('footer_location', 'Annur, Coimbatore District, Tamil Nadu, India', 'Footer location line'),
  ('footer_credits', 'தகவல் ஆதாரம் / Sources: <a href="https://ta.wikipedia.org/wiki/%E0%AE%85%E0%AE%A9%E0%AF%8D%E0%AE%A9%E0%AF%82%E0%AE%B0%E0%AF%8D_%E0%AE%86%E0%AE%A9%E0%AF%88%E0%AE%AE%E0%AE%B2%E0%AF%88_%E0%AE%95%E0%AE%B0%E0%AF%81%E0%AE%AA%E0%AF%8D%E0%AE%AA%E0%AE%B0%E0%AE%BE%E0%AE%AF%E0%AE%9A%E0%AF%81%E0%AE%B5%E0%AE%BE%E0%AE%AE%E0%AE%BF_%E0%AE%95%E0%AF%8B%E0%AE%AF%E0%AE%BF%E0%AE%B2%E0%AF%8D" target="_blank" rel="noopener noreferrer">தமிழ் விக்கிப்பீடியா</a> (<a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a>) · <a href="https://www.google.com/maps/place/Anaimalai+Karupparayan+Temple/@11.2331743,77.0994511,17z" target="_blank" rel="noopener noreferrer">Google Maps</a> <br> படங்கள்: Google Maps-இல் பக்தர்களால் பகிரப்பட்டவை. உரிமை அந்தந்தப் புகைப்படக் கலைஞர்களுக்கே.<br> Photographs contributed by visitors on Google Maps; copyright remains with the individual photographers.', 'Sources / photo credits. Links allowed'),
  ('footer_copyright', '&copy; 2026 அன்னூர் ஆனைமலை கருப்பராயசுவாமி கோயில்', 'Copyright line');
