INSERT INTO `about_paragraphs` (`body_ta`, `body_en`, `sort_order`) VALUES
  ('அன்னூர் ஆனைமலை கருப்பராயசுவாமி கோயில் தமிழ்நாட்டில் கோயம்புத்தூர் மாவட்டம், அன்னூர் என்னும் ஊரில் அமைந்துள்ள ஒரு கிராமக் கோயிலாகும்.', 'The Annur Anaimalai Karupparayaswami Temple is a revered village temple situated in Annur, Coimbatore District, Tamil Nadu. This sacred shrine is dedicated to Lord Karupparayan, a powerful guardian deity deeply venerated across the Tamil countryside.', '0'),
  ('இக்கோயில் முதன்மைத் திருக்கோயில் என்ற வகைப்பாட்டில் இந்து அறநிலையத்துறையின் கட்டுப்பாட்டில் உள்ளது. பரம்பரை அல்லாத அறங்காவலர் அமைப்பால் நிர்வகிக்கப்படுகிறது.', 'Classified as a "Thirukkoyil" (sacred temple), it is administered under the Hindu Religious and Charitable Endowments Department and managed by non-hereditary trustees (Arangavalars).', '10');
INSERT INTO `about_rows` (`label`, `value_ta`, `value_en`, `sort_order`) VALUES
  ('கோயில் பெயர்', 'அருள்மிகு ஆனைமலை கருப்பராயர் திருக்கோவில்', 'Arulmiku Anaimalai Karupparayar Thirukkoyil', '0'),
  ('அமைவிடம் / Location', 'அன்னூர், அன்னூர் வட்டம்', 'Annur, Annur Taluk, Coimbatore', '10'),
  ('மூலவர் / Main Deity', 'கருப்பராயன்', 'Lord Karupparayan', '20'),
  ('சட்டமன்றத் தொகுதி', 'அவிநாசி', 'Avinashi Assembly Constituency', '30'),
  ('மக்களவைத் தொகுதி', 'நீலகிரி', 'Nilgiris Parliamentary Constituency', '40'),
  ('அஞ்சல் குறியீடு / Pincode', '641653', NULL, '50'),
  ('நிர்வாகம் / Administration', 'இந்து அறநிலையத்துறை — பரம்பரை அல்லாத அறங்காவலர்', 'HR&CE Dept — Non-hereditary Trustees', '60');
INSERT INTO `history_entries` (`title_ta`, `title_en`, `body_ta`, `body_en`, `sort_order`) VALUES
  ('பத்தொன்பதாம் நூற்றாண்டு', '19th Century Origins', 'இக்கோயில் பத்தொன்பதாம் நூற்றாண்டைச் சேர்ந்தது. நீண்ட வரலாற்றுப் பின்னணியுடன் அன்னூர் கிராமத்தின் மையமாக விளங்குகிறது.', 'This temple dates back to the 19th century and stands as the spiritual heart of Annur village. It is classified as a "Thirukkoyil" under the Hindu Religious and Charitable Endowments Department.', '0'),
  ('கோயில் அமைப்பு', 'Temple Architecture', 'இக்கோயிலில் கருப்பராயன் சன்னதி மற்றும் கோபுரம் உள்ளது. நுழைவாயிலின் இடது புறம் கேரள அமைப்பில் கம்பீரமாக அமைக்கப்பட்ட கருவறையில் அருள்மிகு ஆனைமலை கருப்பராயர் வடக்கு நோக்கி வீற்றிருக்கிறார். கருப்பராயருக்கு நேர் எதிரில் பிரம்மாண்டமான யானை மற்றும் குதிரை சிலைகள் உள்ளன.', 'The temple features a Gopuram and a main shrine designed in Kerala style. Lord Anaimalai Karupparayar is seated facing north in the sanctum on the left side of the entrance. Grand elephant and horse statues stand majestically in front of the deity — Karupparayar standing on the elephant''s ambari is a breathtaking sight.', '10'),
  ('வேம்பரசு விநாயகர் & புனித மரங்கள்', 'Vemparasu Vinayakar & Sacred Trees', 'நுழைவாயிலின் வலது புறம் தனித்துவமாக வேம்பரசு விநாயகர் சன்னதி தனி மேடையில் அமைந்துள்ளது. வேப்ப மரமும் அரச மரமும் அருகருகே அமைந்துள்ள மரங்களின் அடியில் விநாயகர் அமர்ந்திருப்பதால் வேம்பரசு விநாயகர் என்ற பெயர் பெற்றது. </p> <p> அரச மரமும் வேப்ப மரமும் இணைந்திருப்பது சிவசக்தியின் வெளிப்பாடு — அரசு சிவனாகவும், வேம்பு சக்தியாகவும் கருதப்படுவதால், இவ்விடம் தெய்வ சாந்நித்தியம் நிறைந்ததாகத் திகழ்கிறது. பிள்ளையாரையும் மரங்களையும் சுற்றி வழிபட்டு வருவோர்க்குச் சந்தான பாக்கியம் உண்டாகும் என்பது ஐதீகம்.', 'On the right side of the entrance, the unique Vemparasu Vinayakar shrine sits on a separate raised platform. The deity is named "Vemparasu" because it sits beneath intertwined Neem (Vembu) and Peepal (Arasu) trees — a rare and sacred natural formation. The paired trees are held to embody Siva and Sakti, and devotees who circumambulate the trees and the shrine are traditionally believed to be blessed with children.', '20'),
  ('பிற சன்னதிகள்', 'Other Shrines & Sculptures', 'கருப்பராயர் சுவாமிக்கு நேர் எதிர்ப்புறம் தெற்கு நோக்கி ஸ்ரீ மகா முனிஸ்வரர் இரட்டை முனிகளாக கம்பீரமாக வீற்றிருக்கின்றனர். கருப்பராயர் சன்னதிக்கு இடது புறமாக புற்றுடன் கூடிய நாகர் ஸ்தலமும், பல்லவர் காலத்து மதுரை வீரன் பொம்மி தேவி புடைப்பு சிலையும், சப்த கன்னிகள் மேடையும் உள்ளன.', 'Directly opposite the main deity and facing south, Sri Maha Muniswarar sits as twin sages. Adjacent to Karupparayar''s shrine are the Nagar Sthalam (snake shrine with anthill), a Pallava-era relief sculpture of Madhurai Veeran and Pommi Devi, and the Saptha Kannikal (Seven Maidens) platform.', '30');
INSERT INTO `deity_cards` (`icon`, `name_ta`, `name_en`, `desc_ta`, `desc_en`, `sort_order`) VALUES
  ('⚔', 'அருள்மிகு ஆனைமலை கருப்பராயர்', 'Lord Anaimalai Karupparayar', 'கோயிலின் மூலவர். கேரள அமைப்பில் கம்பீரமாக வடக்கு நோக்கி வீற்றிருக்கிறார். யானையின் மீது அம்பாரியில் கம்பீரமாக நின்றிருக்கும் கருப்பராயரை பார்ப்பதற்கே மெய்சிலிர்க்கும்.', 'The presiding deity, seated facing north in a Kerala-style shrine. A majestic sight atop the elephant''s ambari with grand horse statues standing before him — a truly awe-inspiring vision.', '0'),
  ('🐘', 'வேம்பரசு விநாயகர்', 'Vemparasu Vinayakar', 'வேப்ப மரமும் அரச மரமும் அருகருகே அமைந்துள்ள மரங்களின் அடியில் தனி மேடையில் அமர்ந்திருப்பதால் வேம்பரசு விநாயகர் என்ற பெயர் பெற்றது.', 'Named "Vemparasu" as the deity sits beneath intertwined Neem (Vembu) and Peepal (Arasu) trees on a raised platform at the entrance''s right side.', '10'),
  ('🔱', 'ஸ்ரீ மகா முனிஸ்வரர்', 'Sri Maha Muniswarar', 'கருப்பராயருக்கு நேர் எதிர்ப்புறம் தெற்கு நோக்கி இரட்டை முனிகளாக கம்பீரமாக வீற்றிருக்கின்றனர்.', 'Seated directly opposite the main deity and facing south as twin sages, Sri Maha Muniswarar is a revered presence in the temple complex.', '20'),
  ('🐍', 'நாகர் ஸ்தலம்', 'Nagar Sthalam', 'கருப்பராயர் சன்னதிக்கு இடது புறமாக புற்றுடன் கூடிய நாகர் ஸ்தலம் அமைந்துள்ளது.', 'The sacred snake shrine with an anthill, located to the left of the Karupparayar sanctum.', '30'),
  ('🗡', 'மதுரை வீரன் & பொம்மி தேவி', 'Madhurai Veeran & Pommi Devi', 'பல்லவர் காலத்து புடைப்பு சிற்பமாக மதுரை வீரன் பொம்மி தேவி சிலை அமைந்துள்ளது.', 'A Pallava-era relief sculpture depicting Madhurai Veeran and Pommi Devi — an ancient artistic heritage of the temple.', '40'),
  ('👸', 'சப்த கன்னிகள்', 'Saptha Kannikal', 'கன்னிமார் என்று சொல்லக்கூடிய சப்த கன்னிகள் மேடை உள்ளது. ஆடி 18ஆம் தேதி சிறப்பு பூஜை நடைபெறும்.', 'The Seven Maidens platform — a special pooja is held on Aadi 18th with offerings and cloth given to girls and women devotees.', '50');
INSERT INTO `festival_items` (`month_ta`, `month_en`, `title_ta`, `title_en`, `body_ta`, `body_en`, `sort_order`) VALUES
  ('மாசி', 'Masi<br>(Feb-Mar)', 'மகா சிவராத்திரி', 'Maha Sivarathiri', 'ஒவ்வொரு ஆண்டும் தமிழ் மாதமான மாசியில் மகா சிவராத்திரி விழா சிறப்பாகக் கொண்டாடப்படுகிறது. அந்நாளில் இரவு முழுவதும் வழிபாடுகள் நடைபெற்று, அதிகாலை சிறப்பு பூஜை நடத்தப்படுகிறது.', 'Maha Sivarathiri is celebrated grandly every year during the Tamil month of Masi, with worship continuing through the night and a special pooja at dawn.', '0'),
  ('ஆடி', 'Aadi<br>(Jul-Aug)', 'ஆடி 18 — கன்னிமார் பூஜை & ஆடிப்பெருக்கு', 'Aadi 18 — Kanniamman Festival & Aadi Perukku', 'ஆடி மாதம் 18ஆம் தேதி கன்னிமார் சாமிக்கு (சப்தகன்னிகள்) பலவித பதார்த்தங்களை படைத்து பூஜை செய்து, பெண் குழந்தைகள் மற்றும் சுமங்கலி பெண்களுக்கு துணிகளைக் கொடுத்து கன்னிமாரின் அருளினைப் பெறுவார்கள். ஆடி மாதம் பெரும்பாலான சுற்றுப்புற கிராம மக்கள் புதன், ஞாயிறு கிழமைகளில் பொங்கல் வைத்து, படையல் இட்டு, கிடாய் வெட்டி பூஜை செய்து வழிபட்டு இறைவனின் திருவருள் பெறுவர். ஆடி மாதம் பூஜை செய்ய இயலாதவர்கள் புரட்டாசி, கார்த்திகை மற்றும் மார்கழி மாதங்களைத் தவிர்த்து மற்ற மாதங்களில் பூஜையினைச் செய்து நேர்த்திக் கடனை நிறைவேற்றுவார்கள்.', 'On Aadi 18th, special pooja for Saptha Kannikal with various offerings. Cloth is given to girls and married women to receive the Kanniamman''s blessings. Through Aadi, villagers from the surrounding area gather on Wednesdays and Sundays to cook Pongal and make traditional offerings. Those unable to worship during Aadi fulfil their vows in other months, avoiding Purattasi, Karthigai and Margazhi.', '10'),
  ('கார்த்திகை', 'Karthigai<br>(Nov-Dec)', 'கார்த்திகை தீபம்', 'Karthigai Deepam — Festival of Lights', 'கார்த்திகை மாதம் கார்த்திகை தீபத்தன்று தீபத்தூணில் மாலை ஆறு மணி அளவில் தீபம் ஏற்றி சிறப்பு பூஜை நடைபெறும்.', 'During Karthigai month, a grand lamp is lit on the Deepa Pillar at 6 PM on Karthigai Deepam day, accompanied by special pooja celebrations.', '20'),
  ('மார்கழி', 'Margazhi<br>(Dec-Jan)', 'மார்கழி 30 நாள் சிறப்பு பூஜை', '30-Day Margazhi Special Worship', 'மார்கழி மாதம் 30 நாட்களும் அதிகாலை 6 மணிக்கு சிறப்பு கட்டளை பூஜை நடைபெறும். பக்தர்கள் தங்களுக்கு விருப்பமான அல்லது அவர்கள் பிறந்த நட்சத்திர நாட்களில் கட்டளையை ஏற்று பூஜையை சிறப்படைய செய்வார்கள்.', 'All 30 days of Margazhi month feature special dawn pooja at 6 AM. Devotees can sponsor the pooja on their birth star days and receive divine blessings throughout this sacred month.', '30'),
  ('மாதாந்திர', 'Monthly', 'சங்கடஹர சதுர்த்தி & அமாவாசை', 'Sangadahara Chaturthi & Amavasai', 'ஒவ்வொரு மாதமும் சங்கடஹர சதுர்த்தி அன்று மாலை 6 மணி அளவில் வேம்பரசு விநாயகருக்கு அபிஷேக பூஜை அலங்கார பூஜை சிறப்பாக நடைபெறும். ஒவ்வொரு மாதமும் அமாவாசை அன்று திரளாக மக்கள் வந்து பூஜையில் கலந்து இறையருள் பெறுவார்கள்; அன்று மதியம் அன்னதானம் நடைபெறும்.', 'Monthly Sangadahara Chaturthi at 6 PM with abhisheka and alankara pooja for Vemparasu Vinayakar. On every Amavasai (new moon), large crowds of devotees gather for worship and receive divine grace, followed by annadhanam (free community meal) at midday.', '40'),
  ('சிறப்பு', 'Special<br>Days', 'தமிழ் புத்தாண்டு, தீபாவளி & தைப்பொங்கல்', 'Tamil New Year, Deepavali & Thai Pongal', 'தமிழ் புத்தாண்டு, ஆடிப்பெருக்கு, தீபாவளி மற்றும் தைப்பொங்கல் திரு நாட்களில் சிறப்பு அலங்கார பூஜை நடைபெறும்.', 'Grand decoration and special pooja ceremonies are held on Tamil New Year, Aadi Perukku, Deepavali, and Thai Pongal — the most auspicious days in the Tamil calendar.', '50');
INSERT INTO `location_items` (`icon`, `label`, `value_ta`, `value_en`, `sort_order`) VALUES
  ('📍', 'முகவரி / Address', 'அருள்மிகு ஆனைமலை கருப்பராயர் திருக்கோவில்,<br>அன்னூர் — அவிநாசி — மேட்டுப்பாளையம் சாலை,<br>அன்னூர், தமிழ்நாடு — 641653', 'Annur – Avinashi – Mettupalayam Rd, Annur,<br>Tamil Nadu 641653 · Plus Code 63MX+7Q8', '0'),
  ('🗺', 'ஆயக்கூறுகள் / Coordinates', '11.2331743°N, 77.0994511°E', '<a href="https://www.google.com/maps/place/Anaimalai+Karupparayan+Temple/@11.2331743,77.0994511,17z" target="_blank" rel="noopener noreferrer" style="color: var(--gold-deep);">Google Maps-இல் வழி காட்டு / Get directions ↗</a>', '10'),
  ('🏘', 'ஊர் & வட்டம்', 'அன்னூர், அன்னூர் வட்டம்', 'Annur Village, Annur Taluk', '20'),
  ('🏛', 'மாவட்டம் / District', 'கோயம்புத்தூர் மாவட்டம், தமிழ்நாடு', 'Coimbatore District, Tamil Nadu, India', '30'),
  ('🗳', 'தொகுதிகள் / Constituencies', 'அவிநாசி (சட்டமன்றம்) · நீலகிரி (மக்களவை)', 'Avinashi (Assembly) · Nilgiris (Parliament)', '40'),
  ('📞', 'தொடர்பு / Contact', '<a href="tel:+919843098927" style="color: var(--gold-deep);">098430 98927</a>', 'Listed on Google Maps · 4.6 ★ (9 reviews)', '50');
INSERT INTO `visit_cards` (`icon`, `title_ta`, `title_en`, `body`, `sort_order`) VALUES
  ('🕐', 'கோயில் நேரம்', 'Temple Timings', '<span class="time">மாலை 5:00 மணி முதல்</span> Opens 5:00 PM (per Google Maps) <br><br> <em style="font-family: var(--font-body); opacity: 0.75;"> வருகைக்கு முன் கோயிலைத் தொடர்புகொண்டு நேரத்தை உறுதி செய்யவும்.<br> Please call ahead to confirm timings. </em>', '0'),
  ('🪔', 'பூசையும் தொடர்பும்', 'Worship & Contact', '<span class="time">ஒருகாலப் பூசை</span> இக்கோயிலில் ஒருகாலப் பூசை நடக்கின்றது. மார்கழி மாதம் 30 நாட்களும் அதிகாலை 6 மணிக்குச் சிறப்புக் கட்டளைப் பூசை நடைபெறும். <span class="time"><a href="tel:+919843098927" style="color: inherit;">098430 98927</a></span> A single daily pooja is performed; during Margazhi, a special dawn pooja is held at 6 AM for all 30 days.', '10'),
  ('🙏', 'தரிசன குறிப்பு', 'Darshan Guidelines', 'கோயிலுக்கு வரும் பக்தர்கள் பாரம்பரிய ஆடை அணிந்து வருமாறு கேட்டுக்கொள்ளப்படுகிறார்கள். <br><br> <em style="font-family: var(--font-body); opacity: 0.7;"> Devotees are requested to wear traditional attire when visiting. </em>', '20');
INSERT INTO `gallery_photos` (`filename`, `label`, `caption`, `sort_order`) VALUES
  ('gopuram-front.jpg', 'கோயில் முகப்பு', 'கோயில் முகப்பும் கோபுரமும் — Temple Frontage & Gopuram', '0'),
  ('karupparayar-sannidhi.jpg', 'சன்னதி தரிசனம்', 'மாலை அணிவித்த சன்னதி தரிசனம் — Garlanded shrine with guardian figure', '10'),
  ('kudhirai-madurai-veeran.jpg', 'குதிரை சிலைகள்', 'குதிரை சிலைகளும் காவல் தெய்வமும் — Guardian figure flanked by horse statues', '20'),
  ('vemparasu-vinayakar-padaiyal.jpg', 'விநாயகர் சன்னதி', 'விநாயகர் சன்னதியில் படையல் — Offerings laid at the Vinayakar shrine', '30'),
  ('amman-alangaram.jpg', 'அம்மன் அலங்காரம்', 'மாலை அணிவித்த அம்மன் அலங்காரம் — Garlanded Amman shrine', '40'),
  ('thiruvizha-alangaram.jpg', 'திருவிழா அலங்காரம்', 'பழங்களால் அலங்கரிக்கப்பட்ட திருவிழா தரிசனம் — Festival alankaram with fruit garlands', '50'),
  ('koyil-maalai-neram.jpg', 'மாலை நேரம்', 'கோயில் வளாகம், மாலை நேரம் — A shrine in the temple grounds at dusk', '60');
